size_t nbits = binfo->nbits;
size_t group_ind = min_bit >> LG_BITMAP_GROUP_NBITS;
size_t bit_ind = min_bit & BITMAP_GROUP_NBITS_MASK;

while (group_ind < BITMAP_GROUPS_L0(nbits)) {
    bitmap_t group = bitmap[group_ind];

    // If this is the first group, mask out bits before min_bit
    if (bit_ind != 0) {
        group |= ((bitmap_t)1 << bit_ind) - 1;
    }

    // We are looking for the first UNSET bit.
    // An unset bit in 'group' is a set bit in '~group'.
    bitmap_t inverted_group = ~group;

    // Mask out bits beyond the group boundary if we are at the last group
    // or if the group is partially filled.
    if (group_ind == BITMAP_GROUPS_L0(nbits) - 1) {
        size_t total_bits = (group_ind + 1) << LG_BITMAP_GROUP_NBITS;
        if (total_bits > nbits) {
            inverted_group &= ((bitmap_t)1 << (nbits & BITMAP_GROUP_NBITS_MASK)) - 1;
            // Handle case where nbits is exactly a multiple of group size
            if ((nbits & BITMAP_GROUP_NBITS_MASK) == 0 && nbits > 0) {
                // mask is already correct as all 1s for the group
            }
        }
    }

    if (inverted_group != 0) {
        size_t found_bit = (group_ind << LG_BITMAP_GROUP_NBITS) + ffs_lu(inverted_group);
        if (found_bit < nbits) {
            return found_bit;
        }
    }

    group_ind++;
    bit_ind = 0;
}

return nbits;

